// --- Scroll + Layout Utilities ---
// Scroll-to-Bottom Button Handler
// ==============================
function initializeScrollToBottomButton() {
    const chatContainer = document.getElementById('messages-container');
    const scrollBtn = document.getElementById('scroll-to-bottom-btn');

    if (!chatContainer || !scrollBtn) return;

    let lastScrollTop = 0;
    let isScrollingUp = false;

    function isNearBottom() {
        const threshold = 100; // pixels from bottom
        const distanceFromBottom = chatContainer.scrollHeight - chatContainer.scrollTop - chatContainer.clientHeight;
        return distanceFromBottom < threshold;
    }

    function showButton() {
        if (scrollBtn.style.display === 'none') {
            scrollBtn.style.display = 'flex';
            scrollBtn.classList.remove('hide');
            scrollBtn.classList.add('show');
        }
    }

    function hideButton() {
        if (scrollBtn.style.display === 'flex') {
            scrollBtn.classList.remove('show');
            scrollBtn.classList.add('hide');
            setTimeout(() => {
                if (scrollBtn.style.display === 'flex') {
                    scrollBtn.style.display = 'none';
                }
            }, 300);
        }
    }

    // Scroll event listener
    chatContainer.addEventListener('scroll', () => {
        const currentScrollTop = chatContainer.scrollTop;

        // Detect if scrolling up
        if (currentScrollTop < lastScrollTop) {
            isScrollingUp = true;
            // Show button when scrolling up and not at bottom
            if (!isNearBottom()) {
                showButton();
            }
        }
        // Detect if scrolling down near bottom
        else if (isNearBottom()) {
            hideButton();
        }

        lastScrollTop = currentScrollTop <= 0 ? 0 : currentScrollTop;
    });

    // Click handler
    scrollBtn.addEventListener('click', () => {
        chatContainer.scrollTo({
            top: chatContainer.scrollHeight,
            behavior: 'smooth'
        });
        // Hide button after clicking
        setTimeout(() => {
            hideButton();
        }, 100);
    });

    // Initialize visibility
    if (isNearBottom()) {
        hideButton();
    }
}

// Initialize button when DOM is ready
if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initializeScrollToBottomButton);
} else {
    initializeScrollToBottomButton();
}

