const safeJson = async (resp) => {
    const ct = resp.headers.get('content-type') || '';
    if (!ct.includes('application/json')) {
        const text = await resp.text();
        throw new Error(`Unexpected response (${resp.status}): ${text.slice(0, 200)}`);
    }
    return resp.json();
};

