function navigateToHome({ push = true } = {}) {
    if (IS_GUEST) {
        window.guestConversationId = null;
        try { socket.emit('guest_new_chat'); } catch (_) { }
    }
    showChatView();

    window.conversationParticipantsById = {};
    window.isCollaborativeChat = false;
    setMicButtonVisible(false);
    disableCollabVoice();

    const messages = document.getElementById('messages-container');
    if (messages) {
        messages.innerHTML = '';
        messages.style.display = 'none';
    }

    const start = ensureHomeChatStartContainer();
    if (start) start.style.display = '';

    try {
        enableMessageInput();
        messageInput.value = '';
        try { clearDocumentAttachments({ keepServerFiles: false }); } catch (_) { }

        // FIX: Re-enable and show input area that might be hidden from published/readonly chats
        const chatInputCenter = document.querySelector('.chat-input-center');
        const chatBottomRow = document.querySelector('.chat-bottom-row');
        const attachmentContainer = document.getElementById('attachment-container');

        if (chatInputCenter) chatInputCenter.style.display = '';
        if (chatBottomRow) chatBottomRow.style.display = '';
        if (attachmentContainer) attachmentContainer.style.display = '';

        if (messageInput) messageInput.disabled = false;
        const sendButton = document.getElementById('send-button');
        if (sendButton) sendButton.disabled = false;
    } catch (_) { }

    // FIX: Hide scroll-to-bottom button when navigating to home/new chat
    try {
        const scrollBtn = document.getElementById('scroll-to-bottom-btn');
        if (scrollBtn) {
            scrollBtn.classList.remove('show');
            scrollBtn.classList.add('hide');
            scrollBtn.style.display = 'none';
        }
    } catch (_) { }

    // Reset/close canvas when leaving a chat
    try { closeCanvas(); } catch (_) { }
    resetCanvasForNewChat();
    canvasCurrentConversationId = null;

    // Hide error banner when starting a new chat
    try {
        const banner = document.getElementById('errorTag');
        if (banner) banner.style.display = 'none';
    } catch (_) { }

    // Show trial banner again if trial has ended
    showTrialBannerIfEnded();

    // Update file attach button state
    if (typeof updateFileAttachButtonState === 'function') {
        updateFileAttachButtonState();
    }

    updateCanvasAvailability();
    setPageTitle('');
    if (typeof window.resetActiveFeature === 'function') window.resetActiveFeature();

    if (push) {
        const url = new URL(window.location.href);
        url.pathname = '/app';
        url.search = '';
        window.history.pushState({}, '', url.toString());
    }
}

function navigateToConversation(conversationId, { push = true, resetDocumentDraft = true } = {}) {
    if (IS_GUEST) return;
    const cid = Number(conversationId);
    if (!cid) return;
    showChatView();

    const start = document.querySelector('.chat-start-container');
    if (start) start.style.display = 'none';

    let messages = document.getElementById('messages-container');
    if (!messages) {
        messages = chatBubbleManager.initializeChatContainer(true);
    }
    if (messages) {
        messages.style.display = '';
        messages.innerHTML = '';
    }
    if (resetDocumentDraft) {
        try { clearDocumentAttachments({ keepServerFiles: false }); } catch (_) { }
    }

    if (push) {
        const url = new URL(window.location.href);
        url.pathname = `/app/chat/${cid}`;
        url.search = '';
        window.history.pushState({}, '', url.toString());
    }

    loadConversation(cid);
    ensureConversationParticipants(cid);
    updateCanvasAvailability();
    const knownTitle = getConversationTitleById(cid);
    if (knownTitle) setPageTitle(knownTitle);
}

