// Helper to open preference box with billing tab
function openPreferenceBoxWithBillingTab() {
    const preferenceboxOverlay = document.getElementById('preferenceboxOverlay');
    if (preferenceboxOverlay) {
        preferenceboxOverlay.style.display = 'flex';
        preferenceboxOverlay.classList.add('active');

        // Click the billing tab
        const billingTabLink = document.querySelector('.preferencebox-tab-link[data-tab="billing"]');
        if (billingTabLink) {
            billingTabLink.click();
        }
    }
}

function getModelDisplayName(model) {
    // Expect frontend token values: 'auto', 'free', 'pro', 'super', 'master', 'loard'
    switch (model) {
        case 'auto':
            return "Auto";
        case 'free':
            return "Free";
        case 'pro':
            return "Pro";
        case 'super':
            return "Super";
        case 'master':
            return "Master";
        case 'loard':
            return "Loard";
        default:
            // Defensive fallback: don't reveal raw model ids
            if (typeof model === 'string') {
                const m = model.toLowerCase();
                if (m.includes('3-pro')) return 'Loard';
                if (m.includes('3-flash')) return 'Master';
                if (m.includes('2.5') && m.includes('pro')) return 'Super';
                if (m.includes('2.5') && m.includes('flash') && !m.includes('lite')) return 'Pro';
                if (m.includes('2.5') && m.includes('lite')) return 'Free';
                if (m.includes('2.0')) return 'Free';
            }
            return 'Model';
    }
}

