// --- Streaming + Messaging (UI) ---
// STREAMING HANDLERS
function handleStreamStart(data) {
    // Stop any existing loading animations
    clearTimeout(typingTimeout);
    clearInterval(stageInterval);

    // Hide any previous thinking-status immediately
    clearThinkingTexts();

    // Reset smooth streaming state for new stream
    chatBubbleManager.resetStreamingState();
    stopStreamRequested = false;

    // Keep input enabled during streaming, but switch send button to "stop"
    messageInput.disabled = false;
    messageInput.style.background = "";

    // Create streaming message using optimized system
    currentStreamingMessage = {
        conversation_id: data.conversation_id,
        message_id: data.message_id,
        user_message_id: data.user_message_id,
        content: '',
        is_new: data.is_new,
        is_regeneration: data.is_regeneration,
        isImage: !!data.is_image_request
    };

    if (data && data.conversation_id) {
        setCanvasConversationId(data.conversation_id);
        flushPendingExcalidrawScene();
        if (IS_GUEST) {
            window.guestConversationId = data.conversation_id;
        }
    }

    // For regeneration, find any existing streaming bubble and reset it
    if (data.is_regeneration) {
        // Try to find an existing bubble that's in streaming state
        const existingBubbles = document.querySelectorAll('.chat-bubble.streaming');
        existingBubbles.forEach(b => b.classList.remove('streaming'));
    }

    // Use chatBubbleManager to create or update the bubble
    let bubble = chatBubbleManager.createOrUpdateBubble({
        message_id: data.message_id,
        type: 2,
        is_new: data.is_new,
        sender_user_id: data.sender_user_id
    }, {
        isStreaming: true
    });

    // If this is an image request, show a placeholder
    if (data.is_image_request && bubble) {
        const sc = bubble.querySelector('.streaming-content');
        if (sc) {
            sc.innerHTML = `<span class="image-processing-placeholder" style="color: #888888; font-style: italic;">Image is processing...</span>`;
        } else {
            bubble.insertAdjacentHTML('afterbegin', `<div class="image-processing-placeholder" style="color: #888888; font-style: italic;">Image is processing...</div>`);
        }
    }
    streamingMessageElement = bubble?.querySelector('.streaming-content') || bubble;
    updateSendButtonState();
}

function handleStreamChunk(data) {
    if (data && stoppedStreamMessageIds.has(data.message_id)) {
        return;
    }
    if (
        currentStreamingMessage &&
        currentStreamingMessage.message_id === data.message_id
    ) {
        currentStreamingMessage.content = data.full_content;
        // Skip updating streaming content for image requests
        if (!currentStreamingMessage.isImage) {
            chatBubbleManager.updateStreamingMessage(data.message_id, data.full_content);
        }
        chatBubbleManager.scrollToBottom('auto');
    }
}

function handleStreamComplete(data) {
    if (data && stoppedStreamMessageIds.has(data.message_id)) {
        stoppedStreamMessageIds.delete(data.message_id);
        return;
    }
    if (
        currentStreamingMessage &&
        currentStreamingMessage.message_id === data.message_id
    ) {
        if (IS_GUEST && data?.conversation_id) {
            window.guestConversationId = data.conversation_id;
        }
        // Ensure isImage is set from backend (in stream_complete, too)
        currentStreamingMessage.isImage = !!data.is_image_request || !!currentStreamingMessage.isImage;

        // Get grounding data (citations) if available
        const groundingData = data.grounding || (window.groundingData && window.groundingData[data.message_id]);
        let finalContent = data.final_content;

        // Generate citations HTML (will be added after markdown processing)
        let citationsHTML = '';
        if (groundingData && !currentStreamingMessage.isImage) {
            citationsHTML = generateCitationsHTML(groundingData);
        }

        // Clean up stored grounding data
        if (window.groundingData && window.groundingData[data.message_id]) {
            delete window.groundingData[data.message_id];
        }

        chatBubbleManager.finalizeStreamingMessage(data.message_id, finalContent, {
            model_used: data.model_used,
            user_message_id: data.user_message_id,
            conversation_id: data.conversation_id,
            citationsHTML: currentStreamingMessage.isImage ? '' : citationsHTML,
        });

        // Store model info on the message element for future reference
        const bubble = document.querySelector(`#message-${data.message_id}`);
        if (bubble) {
            bubble.dataset.modelUsed = data.model_used || '';
            bubble.dataset.userMessageId = data.user_message_id || '';
            bubble.dataset.conversationId = data.conversation_id || '';
        }

        // Update user balance display (sender-only in shared chats)
        const isSender = !data.sender_user_id || (window.userData && Number(data.sender_user_id) === Number(window.userData.id));
        if (isSender && data.cost && window.userData) {
            window.userData.balance -= data.cost;
            window.userBalance = window.userData.balance;
            updateBalanceDisplay();
        }

        // If this was a trial message, request updated models/trial status
        if (data.is_trial) {
            socket.emit('get_available_models');
        }

        // Clear streaming state
        currentStreamingMessage = null;
        streamingMessageElement = null;

        // Re-enable input + restore send button
        enableMessageInput();
        stopStreamRequested = false;

        // Clear attachments only (do not wipe typed text)
        clearAttachments({ keepServerFiles: true });
    }
}

function handleStreamError(data) {
    if (data && stoppedStreamMessageIds.has(data.message_id)) {
        stoppedStreamMessageIds.delete(data.message_id);
        return;
    }
    clearThinkingTexts();
    // Reset smooth streaming state
    chatBubbleManager.resetStreamingState();

    // If error object from socket stream (error: true, message: ...)
    if (data && data.error && data.message) {
        showErrorBanner(data.message);
        // Also clear streaming state etc. as below
        currentStreamingMessage = null;
        streamingMessageElement = null;
        enableMessageInput();
        stopStreamRequested = false;
        clearAttachments({ keepServerFiles: true });
        return;
    }

    const messageWrapper = document.querySelector(`[data-m-id="${data.message_id}"]`);
    if (messageWrapper) {
        messageWrapper.innerHTML = `
            <div class="error-message" style="color: #ff4444; padding: 10px; border: 1px solid #ff4444; border-radius: 8px; margin: 10px 0;">
                <i class="fas fa-exclamation-triangle"></i>
                ${data.message || 'An error occurred while streaming the message.'}
            </div>
        `;
    }

    // Show error dialog for free usage limit errors as well
    if (
        data &&
        typeof data.message === "string" &&
        (
            data.message.toLowerCase().includes("free usage limit") ||
            data.message.toLowerCase().includes("free trial") ||
            data.message.toLowerCase().includes("limit exceeded") ||
            data.message.toLowerCase().includes("usage limit")
        )
    ) {
        showDialog("Limit Reached", data.message);
    }

    // Clear streaming state
    currentStreamingMessage = null;
    streamingMessageElement = null;

    // Re-enable input
    enableMessageInput();
    stopStreamRequested = false;
    // Clear attachments only
    clearAttachments({ keepServerFiles: true });
}

// Helper to show or update error banner above chat input
function showErrorBanner(message) {
    let banner = document.getElementById("errorTag");
    if (!banner) {
        const chatWrapper = document.querySelector(".chat-wrapper");
        if (!chatWrapper) return;
        banner = document.createElement("div");
        banner.id = "errorTag";
        banner.className = "error-banner";
        banner.innerHTML = `
            <span class="error-icon"><i class="fa fa-exclamation-triangle"></i></span>
            <span class="error-text">${message}</span>
            <div class="error-buttons">
                <a id="btnUpgrade" class="btn-upgrade">Upgrade</a>
                <button id="btnCloseBanner" class="btn-close">Close</button>
            </div>
        `;
        chatWrapper.parentNode.insertBefore(banner, chatWrapper);
    } else {
        banner.querySelector(".error-text").innerText = message;
        banner.style.display = "flex";
    }
    // Bind button actions
    const closeBtn = banner.querySelector("#btnCloseBanner");
    const upgradeBtn = banner.querySelector("#btnUpgrade");
    closeBtn.onclick = () => banner.style.display = "none";
    upgradeBtn.onclick = () => {
        openPreferenceBoxWithBillingTab();
    };
}

function createStreamingMessageElement(data) {
    let chatContainer;  // Declare here for broader scope

    if (data.is_new) {
        // Find and remove chat-start-container
        const startContainer = document.querySelector(".chat-start-container");
        if (startContainer) {
            startContainer.remove();
        }

        // Create the new messages-container div
        chatContainer = document.createElement("div");
        chatContainer.id = "messages-container";
        chatContainer.className = "messages-container y-overflow-auto";

        // Find the chat-area-wrapper container
        const chatAreaWrapper = document.querySelector(".chat-area-wrapper");
        if (chatAreaWrapper) {
            // Prepend the new container inside chat-area-wrapper
            chatAreaWrapper.prepend(chatContainer);
        }
    } else {
        // Get existing chat container
        chatContainer = document.getElementById("messages-container");
    }

    // Create message wrapper
    const messageWrapper = document.createElement("div");
    messageWrapper.className = 'message bot-message chatBubble streaming';
    messageWrapper.id = `message-${data.message_id}`;
    messageWrapper.dataset.mId = data.message_id;

    // Create message content with streaming indicator
    messageWrapper.innerHTML = `
        <style>
        @keyframes typing-bounce {
            0%, 80%, 100% { transform: scale(0.8); opacity: 0.5; }
            40% { transform: scale(1.2); opacity: 1; }
        }
        </style>
        <p class="streaming-content">
            <div class="streaming-indicator">
                <div class="typing-dots" style="display:flex;align-items:center;gap:4px;">
                    <span style="width:6px;height:6px;background:#666;border-radius:50%;display:inline-block;animation:typing-bounce 1s infinite ease-in-out;"></span>
                    <span style="width:6px;height:6px;background:#666;border-radius:50%;display:inline-block;animation:typing-bounce 1s infinite ease-in-out 0.2s;"></span>
                    <span style="width:6px;height:6px;background:#666;border-radius:50%;display:inline-block;animation:typing-bounce 1s infinite ease-in-out 0.4s;"></span>
                </div>
                <span style="margin-left: 10px; color: #666;">Apilage AI is typing...</span>
            </div>
        </p>
        <div class="message-icons">
            <button class="message-copy icon-button">
                <i class="fa-solid fa-copy"></i>
            </button>
        </div>
    `;

    // Add to chat container
    chatContainer.appendChild(messageWrapper);

    // Scroll to show the new message
    scrollToBottom();

    return messageWrapper.querySelector('.streaming-content');
}

function updateStreamingMessageElement(content) {
    if (streamingMessageElement) {
        // Remove streaming indicator if it exists
        const streamingIndicator = streamingMessageElement.querySelector('.streaming-indicator');
        if (streamingIndicator) {
            streamingIndicator.remove();
        }

        // Update content with markdown rendering
        const processedContent = processMessageText(content);
        streamingMessageElement.innerHTML = processedContent + '<span class="streaming-cursor">▋</span>';
    }
}

function finalizeStreamingMessage(finalContent) {
    if (streamingMessageElement) {
        // Remove streaming cursor
        const cursor = streamingMessageElement.querySelector('.streaming-cursor');
        if (cursor) {
            cursor.remove();
        }

        // Remove streaming class
        const messageWrapper = streamingMessageElement.closest('.message');
        if (messageWrapper) {
            messageWrapper.classList.remove('streaming');
        }

        // Process and set final content
        const processedContent = processMessageText(finalContent);
        streamingMessageElement.innerHTML = processedContent;

        // Add proper message icons for AI messages
        const messageIcons = messageWrapper?.querySelector('.message-icons');
        if (messageIcons) {
            messageIcons.innerHTML = `
                <a href="#" class="report-bug-link">
                    <button style="background: none; border: none; padding-left: 10px; padding-right: 20px; cursor: pointer;">
                        <i class="fa fa-exclamation-triangle" aria-hidden="true" style="color: #8B0000;"></i>
                    </button>
                </a>
                <button class="message-thumbs-down icon-button" data-message-id="${messageWrapper.dataset.mId}">
                    <i class="fa fa-refresh"></i>
                </button>
                <button class="message-note icon-button blink-button" data-message="${encodeURIComponent(finalContent)}">
                    <i class="fa fa-pencil"></i>
                </button>                <button class="message-mindmap icon-button" data-message-id="${messageWrapper.dataset.mId}" data-message-text="${encodeURIComponent(finalContent)}">
                    <i class="fa fa-brain"></i>
                </button>
                <button class="message-copy icon-button">
                    <i class="fa-solid fa-copy"></i>
                </button>
            `;

            // Add event listeners for the new buttons
            addMessageEventListeners(messageWrapper, {
                m_id: messageWrapper.dataset.mId,
                txt: finalContent,
                t: 2
            });
        }

        // Process any special content (math, code, etc.)
        processMessageContent(streamingMessageElement);
    }
}

function processMessageContent(element) {
    if (element) {
        element.querySelectorAll('img').forEach((img) => {
            if (!img.loading) img.loading = 'lazy';
            img.decoding = 'async';
        });
    }
    // Process MathJax if present
    queueMathJaxTypeset(element);

    // Process code blocks with Prism
    setTimeout(() => {
        const blocks = element.querySelectorAll('pre code');
        if (!blocks.length) return;
        const highlightBlocks = () => {
            blocks.forEach((block) => {
                if (window.Prism) {
                    Prism.highlightElement(block);
                }
                addCodeBlockFeatures(block);
            });
        };
        if (window.Prism) {
            highlightBlocks();
        } else if (typeof ensurePrism === 'function') {
            ensurePrism()
                .then(() => highlightBlocks())
                .catch(() => highlightBlocks());
        } else {
            highlightBlocks();
        }
    }, 100);

    // Process Mermaid diagrams
    setTimeout(() => {
        renderMermaidBlocks(element);
    }, 200);
}

function scrollToBottom() {
    const chatContainer = document.getElementById('messages-container');
    if (chatContainer) {
        chatContainer.scrollTo({
            top: chatContainer.scrollHeight,
            behavior: 'smooth'
        });
    }
}

function updateBalanceDisplay() {
    const balanceElements = document.querySelectorAll(".user-balance");
    balanceElements.forEach((el) => {
        el.textContent = window.userBalance || 0;
    });

    // Also update sidebar credit display
    if (typeof updateSidebarCredit === 'function') {
        updateSidebarCredit();
    }
}

function enableMessageInput() {
    messageInput.disabled = false;
    messageInput.style.background = "";
    messageInput.focus();
    updateSendButtonState();
}

function disableMessageInput() {
    messageInput.disabled = true;
    sendButton.disabled = true;
    sendButton.classList.add("text-muted");
    sendButton.classList.remove("text-primary");
}

function setSendButtonIcon(iconClass) {
    if (!sendButton) return;
    const icon = sendButton.querySelector("i");
    if (icon) {
        icon.className = iconClass;
        return;
    }
    sendButton.innerHTML = `<i class="${iconClass}"></i>`;
}

function updateSendButtonState() {
    if (!sendButton) return;
    const isStreaming = !!currentStreamingMessage;
    if (isStreaming) {
        sendButton.disabled = false;
        sendButton.classList.remove("text-muted");
        sendButton.classList.add("text-primary");
        sendButton.setAttribute("aria-label", "Stop");
        setSendButtonIcon("fa-solid fa-stop");
        return;
    }
    const disabled = messageInput.value.trim() === "" || messageInput.disabled;
    sendButton.disabled = disabled;
    sendButton.classList.toggle("text-muted", disabled);
    sendButton.classList.toggle("text-primary", !disabled);
    sendButton.setAttribute("aria-label", "Send");
    setSendButtonIcon("fa-solid fa-paper-plane");
}

function finalizeStoppedStream() {
    if (!currentStreamingMessage) return;
    const messageId = currentStreamingMessage.message_id;
    const conversationId = currentStreamingMessage.conversation_id;
    const userMessageId = currentStreamingMessage.user_message_id;
    const isImage = !!currentStreamingMessage.isImage;
    const rawContent = typeof currentStreamingMessage.content === 'string' ? currentStreamingMessage.content : '';
    const hasContent = !!rawContent.trim();

    let finalContent = rawContent;
    if (isImage) {
        finalContent = 'Image generation stopped.';
    } else if (!hasContent) {
        finalContent = 'Generation stopped.';
    }

    clearThinkingTexts();

    chatBubbleManager.finalizeStreamingMessage(messageId, finalContent, {
        model_used: '',
        user_message_id: userMessageId,
        conversation_id: conversationId,
        citationsHTML: ''
    });

    const bubble = document.querySelector(`#message-${messageId}`);
    if (bubble) {
        if (userMessageId) bubble.dataset.userMessageId = userMessageId;
        if (conversationId) bubble.dataset.conversationId = conversationId;
    }

    currentStreamingMessage = null;
    streamingMessageElement = null;
    stopStreamRequested = false;
    enableMessageInput();
    clearAttachments({ keepServerFiles: true });
}

function requestStopStreaming() {
    if (!currentStreamingMessage || stopStreamRequested) return;
    stopStreamRequested = true;
    const stopMessageId = currentStreamingMessage.message_id;
    if (stopMessageId) {
        stoppedStreamMessageIds.add(stopMessageId);
    }
    try {
        socket.emit("stop_stream", {
            conversation_id: currentStreamingMessage.conversation_id,
            message_id: currentStreamingMessage.message_id
        });
    } catch (_) { }
    finalizeStoppedStream();
}


// --- Message Sending Flow ---
// --- SEND MESSAGE LOGIC PATCH: include model in payload ---
// (This logic is now handled in sendMessage below, so this old handler is not needed.)

const urlParams = new URLSearchParams(window.location.search);
const query = urlParams.get("q");

const messageInput = document.getElementById("message-input");
if (messageInput) {
    messageInput.value = query;
    messageInput.focus();
}

const removeBtn = document.getElementById("removeImage");

// Extend clearAttachments to also clear the input field and preview
function clearAttachmentsPreview(options = {}) {
    const fileInputEl = document.getElementById("fileInput");
    const previewWrapperEl = document.querySelector(".preview-wrapper");

    if (previewWrapperEl) {
        previewWrapperEl.innerHTML = "";
        previewWrapperEl.style.display = "none";
    }
    if (fileInputEl) fileInputEl.value = "";
    const existingUploads = Array.isArray(window.uploadedAttachments) ? window.uploadedAttachments.slice() : [];
    window.uploadedAttachment = null;
    window.uploadedAttachments = [];
    window.uploadedAttachmentsProcessed = false;
    if (!options.keepServerFiles) {
        abortActiveUploads();
        if (existingUploads.length) {
            existingUploads.forEach((name) => {
                try {
                    fetch(uploadDeleteEndpoint, {
                        method: "POST",
                        headers: { "Content-Type": "application/json" },
                        body: JSON.stringify({ filename: name }),
                        credentials: "include",
                    }).catch(() => { });
                } catch (_) { }
            });
        }
    }
    updateDocumentReferenceVisibility();
}

function getDocumentEntryId(entry) {
    if (!entry) return "";
    if (typeof entry === "object") {
        return entry.id || entry.document_id || entry.doc_id || "";
    }
    return String(entry);
}

function getDocumentEntryFilename(entry) {
    if (!entry || typeof entry !== "object") return "";
    return entry.filename || entry.stored_filename || entry.file || "";
}

function updateDocumentReferenceVisibility() {
    const hasDocs = documentPreviewWrapper && documentPreviewWrapper.querySelectorAll(".document-item").length > 0;
    const hasImages = typeof getCurrentAttachmentCount === "function" && getCurrentAttachmentCount() > 0;
    const hasPendingDocs = documentPreviewWrapper && documentPreviewWrapper.querySelectorAll(".document-item[data-uploading='1']").length > 0;

    if (documentAttachmentContainer) {
        documentAttachmentContainer.style.display = hasDocs ? "block" : "none";
    }

    if (documentReferenceContainer) {
        const shouldShowToggle = hasDocs && !hasImages;
        documentReferenceContainer.style.display = shouldShowToggle ? "inline-flex" : "none";
        if (!shouldShowToggle && documentReferenceToggle) {
            documentReferenceToggle.checked = false;
            window.documentReferenceEnabled = false;
        }
    }

    if (documentReferenceToggle) {
        documentReferenceToggle.disabled = !!hasPendingDocs;
    }

    if (!hasDocs) {
        if (documentReferenceToggle) documentReferenceToggle.checked = false;
        window.documentReferenceEnabled = false;
    }
}

function clearDocumentAttachments(options = {}) {
    const existingDocs = Array.isArray(window.uploadedDocuments) ? window.uploadedDocuments.slice() : [];
    window.uploadedDocuments = [];
    window.documentReferenceEnabled = false;
    if (documentReferenceToggle) documentReferenceToggle.checked = false;
    if (documentPreviewWrapper) {
        documentPreviewWrapper.innerHTML = "";
    }
    if (documentAttachmentContainer) {
        documentAttachmentContainer.style.display = "none";
    }

    if (!options.keepServerFiles) {
        abortActiveDocumentUploads();
        if (existingDocs.length) {
            existingDocs.forEach((entry) => {
                const docId = getDocumentEntryId(entry);
                if (!docId) return;
                const filename = getDocumentEntryFilename(entry);
                try {
                    fetch(documentDeleteEndpoint, {
                        method: "POST",
                        headers: { "Content-Type": "application/json" },
                        body: JSON.stringify({ document_id: docId, filename }),
                        credentials: "include",
                    }).catch(() => { });
                } catch (_) { }
            });
        }
    }
    updateDocumentReferenceVisibility();
}

function getCurrentDocumentCount() {
    const uploadedCount = Array.isArray(window.uploadedDocuments) ? window.uploadedDocuments.length : 0;
    const pendingCount = documentPreviewWrapper ? documentPreviewWrapper.querySelectorAll(".document-item[data-uploading='1']").length : 0;
    return uploadedCount + pendingCount;
}

function ensureDocumentPreviewList() {
    if (!documentPreviewWrapper) return null;
    if (documentAttachmentContainer) {
        documentAttachmentContainer.style.display = "block";
    }
    return documentPreviewWrapper;
}

function removeUploadedDocument(docId) {
    if (!docId) return;
    let removedEntry = null;
    if (Array.isArray(window.uploadedDocuments)) {
        removedEntry = window.uploadedDocuments.find((item) => getDocumentEntryId(item) === docId) || null;
        window.uploadedDocuments = window.uploadedDocuments.filter((item) => getDocumentEntryId(item) !== docId);
    }
    const filename = getDocumentEntryFilename(removedEntry);
    try {
        fetch(documentDeleteEndpoint, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ document_id: docId, filename }),
            credentials: "include",
        }).catch(() => { });
    } catch (_) { }
    updateDocumentReferenceVisibility();
}

function createDocumentItem(file) {
    const item = document.createElement("div");
    item.className = "document-item";
    item.dataset.uploading = "1";
    item.innerHTML = `
        <div class="document-card">
            <div class="document-icon"><i class="fa-solid fa-file-lines"></i></div>
            <div class="document-name"></div>
            <div class="document-spinner">
                <div class="doc-spinner-circle"></div>
            </div>
            <button class="remove-document-item">✖</button>
        </div>
    `;
    const nameEl = item.querySelector(".document-name");
    if (nameEl) nameEl.textContent = file?.name || "document";
    const removeBtnEl = item.querySelector(".remove-document-item");
    removeBtnEl?.addEventListener("click", () => {
        item.dataset.canceled = "1";
        if (item._xhr && item.dataset.uploading === "1") {
            try { item._xhr.abort(); } catch (_) { }
        }
        if (item.dataset.docId) {
            removeUploadedDocument(item.dataset.docId);
        }
        item.remove();
        updateDocumentReferenceVisibility();
    });
    return item;
}

function getDocumentUploadErrorMessage(xhr) {
    try {
        const parsed = JSON.parse(xhr.responseText || "{}");
        if (parsed && parsed.message) return parsed.message;
        if (parsed && typeof parsed.error === "string") return parsed.error;
        if (parsed && parsed.error === true) return "Document upload failed";
        return parsed?.error || "Document upload failed";
    } catch (_) {
        return xhr.responseText || "Document upload failed";
    }
}

function uploadSingleDocument(file, listEl) {
    return new Promise((resolve) => {
        const item = createDocumentItem(file);
        listEl.appendChild(item);

        const spinner = item.querySelector(".document-spinner");
        const nameEl = item.querySelector(".document-name");

        const xhr = new XMLHttpRequest();
        item._xhr = xhr;
        activeDocumentXhrs.add(xhr);

        const formData = new FormData();
        formData.append("document", file);

        xhr.open("POST", documentUploadEndpoint, true);
        xhr.withCredentials = true;

        xhr.onload = function () {
            activeDocumentXhrs.delete(xhr);
            if (item.dataset.canceled === "1") return resolve();
            if (xhr.status === 200) {
                try {
                    const result = JSON.parse(xhr.responseText);
                    const doc = result?.document || (Array.isArray(result?.documents) ? result.documents[0] : null);
                    const docId = doc?.id;
                    const docName = doc?.name || file?.name || "document";
                    const docFilename = doc?.filename || doc?.stored_filename || "";
                    const docMimeType = doc?.mimeType || doc?.mime_type || "";
                    if (docId) {
                        item.dataset.docId = docId;
                        item.dataset.uploading = "0";
                        if (nameEl) nameEl.textContent = docName;
                        if (spinner) spinner.remove();
                        if (!Array.isArray(window.uploadedDocuments)) window.uploadedDocuments = [];
                        window.uploadedDocuments.push({ id: docId, name: docName, filename: docFilename, mimeType: docMimeType });
                        updateDocumentReferenceVisibility();
                        return resolve(docId);
                    }
                } catch (_) {
                    // fall through to error
                }
            }
            const errorMessage = getDocumentUploadErrorMessage(xhr);
            if (spinner) {
                spinner.innerHTML = `<span style="color:#fff;font-size:14px;">!</span>`;
                spinner.style.background = "rgba(255,68,68,0.7)";
            }
            item.dataset.uploading = "0";
            showDialog("Upload failed", errorMessage);
            updateDocumentReferenceVisibility();
            resolve();
        };

        xhr.onerror = function () {
            activeDocumentXhrs.delete(xhr);
            if (item.dataset.canceled === "1") return resolve();
            if (spinner) {
                spinner.innerHTML = `<span style="color:#fff;font-size:14px;">!</span>`;
                spinner.style.background = "rgba(255,68,68,0.7)";
            }
            item.dataset.uploading = "0";
            showDialog("Upload failed", "Network error");
            updateDocumentReferenceVisibility();
            resolve();
        };

        xhr.onabort = function () {
            activeDocumentXhrs.delete(xhr);
            resolve();
        };

        xhr.send(formData);
    });
}

async function uploadDocumentAuto(files) {
    if (IS_GUEST) {
        notifyGuestRestriction();
        return;
    }
    const fileList = Array.isArray(files) ? files : (files ? [files] : []);
    const allowedExt = new Set(["pdf", "txt", "md", "markdown"]);
    const docs = fileList.filter((file) => {
        if (!file) return false;
        if (file.type === "application/pdf") return true;
        if (file.type && file.type.startsWith("text/")) return true;
        const name = String(file.name || "");
        const ext = name.split(".").pop().toLowerCase();
        return allowedExt.has(ext);
    });
    if (!docs.length) {
        showDialog("Error", "Only PDF or text documents are allowed.");
        return;
    }

    const currentCount = getCurrentDocumentCount();
    const remaining = MAX_DOCUMENT_UPLOADS_PER_MESSAGE - currentCount;
    if (remaining <= 0) {
        showDialog("Error", `You can upload up to ${MAX_DOCUMENT_UPLOADS_PER_MESSAGE} documents at a time.`);
        return;
    }

    const toUpload = docs.slice(0, remaining);
    if (docs.length > remaining) {
        showDialog("Error", `You can upload up to ${MAX_DOCUMENT_UPLOADS_PER_MESSAGE} documents at a time.`);
    }

    const listEl = ensureDocumentPreviewList();
    if (!listEl) return;

    for (const file of toUpload) {
        await uploadSingleDocument(file, listEl);
    }

    if (documentInput) documentInput.value = "";
}

