const uploadEndpoint = `${EFFECTIVE_NODE_API_BASE}/upload`;
const uploadDeleteEndpoint = `${EFFECTIVE_NODE_API_BASE}/upload/delete`;
const MAX_UPLOADS_PER_MESSAGE = 5;
let activeUploadXhrs = new Set();
const documentUploadEndpoint = `${EFFECTIVE_NODE_API_BASE}/upload-document`;
const documentDeleteEndpoint = `${EFFECTIVE_NODE_API_BASE}/upload-document/delete`;
const MAX_DOCUMENT_UPLOADS_PER_MESSAGE = 5;
let activeDocumentXhrs = new Set();

function abortActiveUploads() {
    if (!activeUploadXhrs || activeUploadXhrs.size === 0) return;
    activeUploadXhrs.forEach((xhr) => {
        try { xhr.abort(); } catch (_) { }
    });
    activeUploadXhrs.clear();
}

function abortActiveDocumentUploads() {
    if (!activeDocumentXhrs || activeDocumentXhrs.size === 0) return;
    activeDocumentXhrs.forEach((xhr) => {
        try { xhr.abort(); } catch (_) { }
    });
    activeDocumentXhrs.clear();
}

// --- Create or update upload status UI
function showUploadStatus(statusText, color = "#888") {
    if (!previewWrapper) return;
    let statusEl = previewWrapper.querySelector(".upload-status");
    if (!statusEl) {
        statusEl = document.createElement("div");
        statusEl.className = "upload-status";
        statusEl.style.marginTop = "6px";
        statusEl.style.fontSize = "13px";
        previewWrapper.appendChild(statusEl);
    }
    statusEl.style.color = color;
    statusEl.innerText = statusText;
}

function ensurePreviewList() {
    if (!previewWrapper) return null;
    let listEl = previewWrapper.querySelector(".preview-list");
    if (!listEl) {
        previewWrapper.innerHTML = `
            <div class="preview-list" style="display:flex;flex-direction:row;align-items:center;gap:8px;flex-wrap:wrap;"></div>
        `;
        previewWrapper.style.display = "block";
        listEl = previewWrapper.querySelector(".preview-list");
    }
    return listEl;
}

function getCurrentAttachmentCount() {
    const uploadedCount = Array.isArray(window.uploadedAttachments) ? window.uploadedAttachments.length : 0;
    const pendingCount = previewWrapper ? previewWrapper.querySelectorAll(".upload-item[data-uploading='1']").length : 0;
    return uploadedCount + pendingCount;
}

function updateAttachmentState() {
    if (!Array.isArray(window.uploadedAttachments)) window.uploadedAttachments = [];
    window.uploadedAttachment = window.uploadedAttachments[0] || null;
    if (!window.uploadedAttachments.length) {
        window.uploadedAttachmentsProcessed = false;
    }
    const hasItems = previewWrapper && previewWrapper.querySelectorAll(".upload-item").length > 0;
    if (!hasItems && previewWrapper) {
        previewWrapper.innerHTML = "";
        previewWrapper.style.display = "none";
    }
    updateDocumentReferenceVisibility();
}

function removeUploadedAttachment(name) {
    if (!name) return;
    if (Array.isArray(window.uploadedAttachments)) {
        window.uploadedAttachments = window.uploadedAttachments.filter((item) => item !== name);
    }
    window.uploadedAttachment = Array.isArray(window.uploadedAttachments) ? window.uploadedAttachments[0] || null : null;
    try {
        fetch(uploadDeleteEndpoint, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ filename: name }),
            credentials: "include",
        }).catch(() => { });
    } catch (_) { }
    updateDocumentReferenceVisibility();
}

function createUploadItem(file) {
    const item = document.createElement("div");
    item.className = "upload-item";
    item.dataset.uploading = "1";
    item.innerHTML = `
        <div style="position:relative;width:58px;height:58px;">
            <img src="${URL.createObjectURL(file)}" alt="Preview" style="width:58px;height:58px;object-fit:cover;border-radius:10px;opacity:0.9;">
            <div class="upload-spinner" style="position:absolute;inset:0;display:flex;align-items:center;justify-content:center;background:rgba(0,0,0,0.35);border-radius:10px;">
                <div style="width:20px;height:20px;border:2px solid rgba(255,255,255,0.7);border-top-color:#fff;border-radius:50%;animation:spin 0.9s linear infinite;"></div>
            </div>
            <button class="remove-upload-item" style="position:absolute;top:-6px;right:-6px;width:20px;height:20px;border-radius:50%;border:none;background:#fff;color:#ff4444;font-size:14px;cursor:pointer;box-shadow:0 2px 6px rgba(0,0,0,0.2);">✖</button>
        </div>
    `;
    const removeBtn = item.querySelector(".remove-upload-item");
    removeBtn.addEventListener("click", () => {
        item.dataset.canceled = "1";
        if (item._xhr && item.dataset.uploading === "1") {
            try { item._xhr.abort(); } catch (_) { }
        }
        if (item.dataset.filename) {
            removeUploadedAttachment(item.dataset.filename);
        }
        item.remove();
        updateAttachmentState();
    });
    return item;
}

function getUploadErrorMessage(xhr) {
    try {
        const parsed = JSON.parse(xhr.responseText || "{}");
        if (parsed && parsed.message) return parsed.message;
        if (parsed && typeof parsed.error === "string") return parsed.error;
        if (parsed && parsed.error === true) return "Upload failed";
        return parsed?.error || "Upload failed";
    } catch (_) {
        return xhr.responseText || "Upload failed";
    }
}

const IMAGE_OPTIMIZE_MAX_DIM = 2048;
const IMAGE_OPTIMIZE_MIN_BYTES = 2 * 1024 * 1024;
const IMAGE_OPTIMIZE_QUALITY = 0.85;

async function loadImageFromFile(file) {
    return new Promise((resolve, reject) => {
        const url = URL.createObjectURL(file);
        const img = new Image();
        img.onload = () => {
            URL.revokeObjectURL(url);
            resolve(img);
        };
        img.onerror = (err) => {
            URL.revokeObjectURL(url);
            reject(err);
        };
        img.src = url;
    });
}

async function prepareImageForUpload(file) {
    if (!file || !file.type || !file.type.startsWith("image/")) return file;
    if (file.type === "image/gif") return file;
    if (file.size < IMAGE_OPTIMIZE_MIN_BYTES) return file;

    try {
        let img;
        if ("createImageBitmap" in window) {
            img = await createImageBitmap(file);
        } else {
            img = await loadImageFromFile(file);
        }

        const width = img.width || img.naturalWidth || 0;
        const height = img.height || img.naturalHeight || 0;
        if (!width || !height) return file;

        const maxDim = IMAGE_OPTIMIZE_MAX_DIM;
        if (width <= maxDim && height <= maxDim) return file;

        const scale = Math.min(maxDim / width, maxDim / height);
        const targetW = Math.max(1, Math.round(width * scale));
        const targetH = Math.max(1, Math.round(height * scale));

        const canvas = document.createElement("canvas");
        canvas.width = targetW;
        canvas.height = targetH;
        const ctx = canvas.getContext("2d");
        if (!ctx) return file;
        ctx.drawImage(img, 0, 0, targetW, targetH);
        if (img && typeof img.close === "function") {
            try { img.close(); } catch (_) { }
        }

        const outType = file.type === "image/png" ? "image/png" : "image/jpeg";
        const blob = await new Promise((resolve) =>
            canvas.toBlob(resolve, outType, outType === "image/jpeg" ? IMAGE_OPTIMIZE_QUALITY : undefined)
        );
        if (!blob) return file;

        const ext = outType === "image/png" ? "png" : "jpg";
        const baseName = String(file.name || "upload").replace(/\.[^.]+$/, "");
        return new File([blob], `${baseName}.${ext}`, { type: outType });
    } catch (_) {
        return file;
    }
}

function uploadSingleFile(file, listEl) {
    return new Promise((resolve) => {
        const item = createUploadItem(file);
        listEl.appendChild(item);

        const imgEl = item.querySelector("img");
        const spinner = item.querySelector(".upload-spinner");

        const xhr = new XMLHttpRequest();
        item._xhr = xhr;
        activeUploadXhrs.add(xhr);

        const formData = new FormData();
        formData.append("image", file);

        xhr.open("POST", uploadEndpoint, true);
        xhr.withCredentials = true;

        xhr.upload.addEventListener("progress", (e) => {
            if (!e.lengthComputable) return;
        });

        xhr.onload = function () {
            activeUploadXhrs.delete(xhr);
            if (item.dataset.canceled === "1") return resolve();
            if (xhr.status === 200) {
                try {
                    const result = JSON.parse(xhr.responseText);
                    const filename = result?.filename || (Array.isArray(result?.filenames) ? result.filenames[0] : "");
                    if (filename) {
                        item.dataset.filename = filename;
                        item.dataset.uploading = "0";
                        if (imgEl) {
                            imgEl.src = `${getUploadsBase()}/uploads/userimg/${filename}`;
                            imgEl.style.opacity = "1";
                        }
                        if (spinner) spinner.remove();
                        if (!Array.isArray(window.uploadedAttachments)) window.uploadedAttachments = [];
                        window.uploadedAttachments.push(filename);
                        window.uploadedAttachment = window.uploadedAttachments[0] || null;
                        window.uploadedAttachmentsProcessed = true;
                        updateDocumentReferenceVisibility();
                        showUploadStatus("");
                        return resolve(filename);
                    }
                } catch (_) {
                    // fall through to error
                }
            }
            const errorMessage = getUploadErrorMessage(xhr);
            if (spinner) {
                spinner.innerHTML = `<span style="color:#fff;font-size:16px;">!</span>`;
                spinner.style.background = "rgba(255,68,68,0.7)";
            }
            showUploadStatus(`❌ ${errorMessage}`, "#ff4444");
            item.dataset.uploading = "0";
            resolve();
        };

        xhr.onerror = function () {
            activeUploadXhrs.delete(xhr);
            if (item.dataset.canceled === "1") return resolve();
            if (spinner) {
                spinner.innerHTML = `<span style="color:#fff;font-size:16px;">!</span>`;
                spinner.style.background = "rgba(255,68,68,0.7)";
            }
            showUploadStatus("❌ Network error", "#ff4444");
            item.dataset.uploading = "0";
            resolve();
        };

        xhr.onabort = function () {
            activeUploadXhrs.delete(xhr);
            resolve();
        };

        xhr.send(formData);
    });
}

// --- Upload with progress bar (one by one) ---
async function uploadFileAuto(files) {
    if (IS_GUEST) {
        notifyGuestRestriction();
        return;
    }
    const fileList = Array.isArray(files) ? files : (files ? [files] : []);
    const images = fileList.filter((file) => file && file.type && file.type.startsWith("image/"));
    if (!images.length) {
        showUploadStatus("❌ Only image files are allowed", "#ff4444");
        return;
    }

    const currentCount = getCurrentAttachmentCount();
    const remaining = MAX_UPLOADS_PER_MESSAGE - currentCount;
    if (remaining <= 0) {
        showUploadStatus(`❌ You can upload up to ${MAX_UPLOADS_PER_MESSAGE} images at a time`, "#ff4444");
        return;
    }

    const toUpload = images.slice(0, remaining);
    if (images.length > remaining) {
        showUploadStatus(`❌ You can upload up to ${MAX_UPLOADS_PER_MESSAGE} images at a time`, "#ff4444");
    }

    const listEl = ensurePreviewList();
    if (!listEl) return;

    for (const file of toUpload) {
        showUploadStatus("Optimizing image...", "#888");
        const prepared = await prepareImageForUpload(file);
        await uploadSingleFile(prepared, listEl);
    }
}

