// ✅ Unified Drag & Drop Upload (same behavior as select)
["message-input", "previewWrapper"].forEach((idOrEl) => {
    const el = typeof idOrEl === "string" ? document.getElementById(idOrEl) : idOrEl;
    if (!el) return;

    el.addEventListener("dragover", (e) => {
        if (IS_GUEST || window.imageUploadsDisabled) {
            e.preventDefault();
            return;
        }
        e.preventDefault();
        el.classList.add("drag-over");
        showUploadStatus("📸 Drop image to upload", "#007bff");
    });

    el.addEventListener("dragleave", (e) => {
        if (IS_GUEST || window.imageUploadsDisabled) {
            e.preventDefault();
            el.classList.remove("drag-over");
            showUploadStatus("");
            return;
        }
        e.preventDefault();
        el.classList.remove("drag-over");
        showUploadStatus("");
    });

    el.addEventListener("drop", (e) => {
        if (IS_GUEST) {
            e.preventDefault();
            el.classList.remove("drag-over");
            notifyGuestRestriction();
            return;
        }
        if (window.imageUploadsDisabled) {
            e.preventDefault();
            el.classList.remove("drag-over");
            showUploadStatus("Upgrade to Pro to upload images", "#ff4444");
            return;
        }
        e.preventDefault();
        el.classList.remove("drag-over");
        const files = Array.from(e.dataTransfer.files || []).filter((file) => file && file.type && file.type.startsWith("image/"));
        if (files.length) {
            uploadFileAuto(files); // ✅ Same logic as select upload
        } else {
            showUploadStatus("❌ Only image files are allowed", "#ff4444");
        }
    });
});

